    if n == 0:
        return 0
    def _fib(k):
        if k == 0:
            return (0, 1)
        a, b = _fib(k >> 1)
        c = (a * (2 * b - a)) % m
        d = (a * a + b * b) % m
        if k & 1:
            return (d, (c + d) % m)
        return (c, d)
    return _fib(n)[0]
